scale * 6; // 48px\n$s52: $scale * 6.5; // 52px\n$s56: $scale * 7; // 56px\n$s60: $scale * 7.5; // 60px\n$s64: $scale * 8; // 64px\n$s72: $scale * 9; // 72px\n$s80: $scale * 10; // 80px\n$s84: $scale * 10; // 84px\n$s88: $scale * 11; // 88px\n$s96: $scale * 12; // 96px\n$s104: $scale * 13; // 104px\n$s112: $scale * 14; // 112px\n$s120: $scale * 15; // 120px\n$s128: $scale * 16; // 128px\n$s136: $scale * 17; // 136px\n$s144: $scale * 18; // 144px\n$s152: $scale * 19; // 152px\n$s160: $scale * 20; // 160px\n$s168: $scale * 21; // 168px\n\n/* ––––––––––––––––– */\n/* Typographic Scale */\n/* ––––––––––––––––– */\n$fs-xxs: $s10; // 10px\n$fs-xs: $s12; // 12px\n$fs-s: $s14; // 14px\n$fs-m: $s16; // 16px\n$fs-l: $s24; // 24px\n$fs-xl: $s32; // 32px\n$fs-xxl: $s40; // 40px\n\n/* ––––––––––––––––– */\n/*    Transitions    */\n/* ––––––––––––––––– */\n$transition-fast: all 0.05s ease-in-out;\n$transition-normal: all 0.1s ease-in-out;\n$transition-slow: all 0.25s ease-in-out;\n\n/* ––––––––––––––––– */\n/*    Breakpoints    */\n/* ––––––––––––––––– */\n$sm: 576px;\n$md: 768px;\n$lg: 992px;\n$xl: 1200px;\n$xxl: 1440px;\n$xxxl: 1600px;\n$xxxxl: 2000px;\n\n/* ––––––––––––––––– */\n/*    Font Weights   */\n/* ––––––––––––––––– */\n// Nova uses Saans 400 and 500 only. These point at Stardust's weight tokens so\n// every existing use inherits them; emphasis of any strength is Medium.\n$fw-book: var(--font-weight-regular);\n$fw-medium: var(--font-weight-medium);\n$fw-semibold: var(--font-weight-medium);\n$fw-heavy: var(--font-weight-medium);\n$fw-black: var(--font-weight-medium);\n\n/* –––––––––––––––––– */\n/*    Fixed measures  */\n/* –––––––––––––––––– */\n$header-height: $s64;\n$footer-height: $s64;\n$sidebar-width: 20rem;\n$sidebar-width-md: 15rem;\n$sidebar-width-lg: 25rem;\n$settings-slide-in-width: 35rem;\n$activity-container-max-width: 57rem;\n$course-navigation-height: $s40;\n$top-banner-height: $s40;\n$tab-bar-height: $s64;\n$input-height: $s40;\n$textarea-height: 10rem;\